[[gnu::flatten, gnu::noinline]]
void kernel_seidel_2d(int tsteps, auto A) {
	using namespace noarr;

	// grid size in each spatial dimension
	auto n_i = A | get_length<'i'>();
	auto n_j = A | get_length<'j'>();

	// Precompute reciprocal to avoid a division in the inner stencil
	const num_t inv9 = num_t(1.0) / num_t(9.0);

	// Tile sizes for cache-friendly blocking.
	// These are tunable; chosen to give reasonable tiles for L1/L2.
	constexpr std::size_t tile_i = 32;
	constexpr std::size_t tile_j = 64;

	// Proto-structure describing:
	//  - interior domain: i,j in [1, n-2]
	//  - 2D tiling: i -> (I, i), j -> (J, j)
	//
	// We use into_blocks_dynamic so that N-2 does not need to be a multiple
	// of tile_i/tile_j; any incomplete tiles are handled internally via
	// an extra "presence" dimension and are simply not visited.
	//
	// Dimensional order after these transforms is effectively:
	//   I (row tiles), i (rows within tile),
	//   J (column tiles), j (cols within tile)
	//
	// This is equivalent to the original lexicographic order:
	//   for i
	//     for j
	// just grouped into tiles. All per-time-step Gauss–Seidel dependencies
	// on north/north-west/north-east and west neighbors remain satisfied.
