		slice<'i'>(1, n_i - 2) ^
		slice<'j'>(1, n_j - 2) ^
		noarr::into_blocks_dynamic<'i', 'I', 'i', 'p'>(tile_i) ^
		noarr::into_blocks_dynamic<'j', 'J', 'j', 'q'>(tile_j);

	#pragma scop
	for (int t = 0; t <= tsteps - 1; t++) {
		traverser(A)
			.order(interior_order)
			.for_each([&](auto state) {
				// 'state' contains the original i,j indices (in [1, n-2]),
				// even though the traverser internally iterates over
				// (I, i, J, j) tiles. This makes neighbor() and A[state]
				// behave exactly as in the baseline implementation.

