// A: i x j
//
// This is an in‑place Gauss–Seidel 9‑point stencil over the interior of A:
//   A[i,j] = (1/9) * sum of the 3×3 Moore neighborhood around (i,j)
// for i,j in [1, n-2].  The update order (time t outer, then i, then j)
// is part of the semantics (true Gauss–Seidel), so any transformation must
// preserve the lexicographic (t, i, j) execution order of interior points.
//
// Optimizations applied here:
//   * Replace division by 9.0 with multiplication by a precomputed inv9.
//   * Block the i‑dimension (rows) using noarr::into_blocks_dynamic, and
//     hoist the block index 'I'. This introduces a loop over row tiles:
//       for I (tile index)  // new
//         for i in tile I   // original i
//           for j           // original j
//     which still produces the same global (i, j) order as the original
//     row‑major sweep (only grouped by tiles), so Gauss–Seidel dependencies
//     are preserved.
//   * Slightly reduce state arithmetic by reusing partially shifted states.
[[gnu::flatten, gnu::noinline]]
void kernel_seidel_2d(int tsteps, auto A) {
	using namespace noarr;

	// Grid size in each spatial dimension
	auto n_i = A | get_length<'i'>();
	auto n_j = A | get_length<'j'>();

	// Precomputed reciprocal: replaces sum / 9.0 with sum * inv9
	constexpr num_t inv9 = num_t(1.0) / num_t(9.0);

	// Tile size in the i-dimension (rows). This only affects how the
	// traverser organizes the iteration, not the observable (i,j) order.
	constexpr std::size_t tile_i = 32;

	// Proto-structure for restricting the traversal to the interior points
	// i, j in [1, n-2].
	auto interior =
		slice<'i'>(1, n_i - 2) ^
		slice<'j'>(1, n_j - 2);

	// Block the i-dimension into tiles of height tile_i.
	// into_blocks_dynamic<'i','I','i','r'>:
	//   - 'i'      : original row index (still visible in the state)
	//   - 'I'      : tile index over rows (used internally by traverser)
	//   - 'r'      : presence guard for the last partial tile
	//
	// Using into_blocks_dynamic (rather than into_blocks) correctly
	// handles cases where (n_i - 2) is not a multiple of tile_i.
	auto block_i =
		into_blocks_dynamic<'i', 'I', 'i', 'r'>(tile_i);

	// Full traversal order proto:
	//   1. restrict to interior (slice)
	//   2. block rows into tiles (into_blocks_dynamic)
	//   3. hoist 'I' so that the loop over row tiles is outermost
	//
	// Importantly, this still visits (i,j) in the same lexicographic
	// order as the original code: for each time step t,
	//   i = 1..n_i-2, j = 1..n_j-2
	// only grouped into tiles along i.
	auto order_proto = interior ^ block_i ^ hoist<'I'>();

	#pragma scop
	for (int t = 0; t <= tsteps - 1; t++) {
		// Traverse only interior points, in the original row-major order,
		// but organized internally into row tiles.
		traverser(A)
			.order(order_proto)
			.for_each([&](auto state) {
				// state contains original indices 'i' and 'j' in the
				// interior range [1, n-2]; it does *not* contain the
				// artificial tiling dimensions ('I', 'r'), which are
				// only used internally by the traverser.

				auto s = state;

				// Reuse some shifted states to reduce state arithmetic.
				// We still use noarr::neighbor, but avoid recomputing
				// the same i-shifts multiple times.
				auto s_im1 = neighbor<'i'>(s, -1);
				auto s_ip1 = neighbor<'i'>(s, +1);
				auto s_jm1 = neighbor<'j'>(s, -1);
				auto s_jp1 = neighbor<'j'>(s, +1);

				auto s_im1_jm1 = neighbor<'j'>(s_im1, -1);
				auto s_im1_jp1 = neighbor<'j'>(s_im1, +1);

				auto s_ip1_jm1 = neighbor<'j'>(s_ip1, -1);
				auto s_ip1_jp1 = neighbor<'j'>(s_ip1, +1);

				// Center
				auto s_i_j = s;

				// 9‑point sum over the Moore neighborhood of (i,j)
				num_t sum =
					A[s_im1_jm1] + A[s_im1]     + A[s_im1_jp1] +
					A[s_jm1]     + A[s_i_j]     + A[s_jp1]     +
					A[s_ip1_jm1] + A[s_ip1]     + A[s_ip1_jp1];

				// In-place Gauss–Seidel update
				A[s_i_j] = sum * inv9;
			});
