// Semantics:
//   In-place Gauss–Seidel 9-point stencil over the interior of A.
//   For each time-step t and interior point (i,j) with 1 <= i,j <= N-2:
//
//     A[i,j] = (1/9) * ( A[i-1,j-1] + A[i-1,j] + A[i-1,j+1]
//                       + A[i,  j-1] + A[i,  j] + A[i,  j+1]
//                       + A[i+1,j-1] + A[i+1,j] + A[i+1,j+1] )
//
//   The update order within a time-step is lexicographic: i outer, j inner.
//   Our transformations preserve this order exactly (Gauss–Seidel semantics).
[[gnu::flatten, gnu::noinline]]
void kernel_seidel_2d(int tsteps, auto A) {
	using namespace noarr;

	// Grid size in each spatial dimension
	auto n_i = A | get_length<'i'>();
	auto n_j = A | get_length<'j'>();

	// Precompute reciprocal to avoid a floating-point division in the inner loop.
	const num_t inv9 = num_t(1.0) / num_t(9.0);

	// --------------------------------------------------------------------
	// Spatial blocking (tiling) configuration
	// --------------------------------------------------------------------
	// We block in both i (rows) and j (columns) to improve cache locality.
	// The layout is row-major with j as the contiguous dimension.
	//
	// The tiling is done via `into_blocks_dynamic`, which:
	//   - splits a dimension Dim into (DimMajor, DimMinor),
	//   - adds a "presence" dimension (here 'r' for i, 's' for j) that
	//     ensures partial tiles at the edges are handled correctly,
	//   - *preserves* the logical lexicographic order of (i,j) when
	//     used with traverser().for_each().
	//
	// The traversal order after applying these proto-structures is:
	//   I (row tiles), i (rows within tile), r (row-presence),
	//   J (col tiles), j (cols within tile), s (col-presence)
	// which, after mapping back to (i,j), is still:
	//   i increasing, j increasing within each row.
	constexpr std::size_t tile_i = 32; // tile height  (rows)
	constexpr std::size_t tile_j = 32; // tile width   (columns)

	// Dynamic blocking in i and j with per-element guards:
	constexpr auto blk_i =
		noarr::into_blocks_dynamic<'i', 'I', 'i', 'r'>(noarr::lit<tile_i>);
	constexpr auto blk_j =
		noarr::into_blocks_dynamic<'j', 'J', 'j', 's'>(noarr::lit<tile_j>);

	// Restrict traversal to the interior points only: i,j in [1, n-2].
	// Using `slice` via `order` keeps the indices seen in the lambda
	// as the *original* i,j (1 .. n-2), which is important for neighbor().
