	for (int t = 0; t < tsteps; t++) {
		// Traversal:
		//   - interior: skip the boundary rows/cols (never updated),
		//   - blk_i, blk_j: iterate interior in cache-friendly tiles,
		//   - for_each: visits each interior (i,j) once in the same
		//     lexicographic order as the original implementation.
		noarr::traverser(A)
			.order(interior ^ blk_i ^ blk_j)
			.for_each([&](auto state) {
				// `state` is a Noarr state describing the current interior cell.
				// It contains indices 'i' and 'j' in the *original* structure,
				// independent of the tiling dimensions I,J,r,s used internally
				// by the traverser.
				auto s = state;

				// Build states for all 8 neighbors and the center.
				// neighbor<'i','j'>(s, di, dj) returns a new state with
				// indices shifted by (di,dj) in the (i,j) grid.
				auto s_im1_jm1 = noarr::neighbor<'i', 'j'>(s, -1, -1);
				auto s_im1_j   = noarr::neighbor<'i'>(s, -1);
				auto s_im1_jp1 = noarr::neighbor<'i', 'j'>(s, -1, +1);

				auto s_i_jm1   = noarr::neighbor<'j'>(s, -1);
				auto s_i_j     = s;
				auto s_i_jp1   = noarr::neighbor<'j'>(s, +1);

				auto s_ip1_jm1 = noarr::neighbor<'i', 'j'>(s, +1, -1);
				auto s_ip1_j   = noarr::neighbor<'i'>(s, +1);
				auto s_ip1_jp1 = noarr::neighbor<'i', 'j'>(s, +1, +1);

				// 9-point stencil sum
				num_t sum =
					A[s_im1_jm1] + A[s_im1_j] + A[s_im1_jp1] +
					A[s_i_jm1]   + A[s_i_j]   + A[s_i_jp1] +
					A[s_ip1_jm1] + A[s_ip1_j] + A[s_ip1_jp1];

				// Use multiplication by inv9 instead of a division by 9.0
				// for better throughput (one multiply vs. one divide).
				A[s_i_j] = sum * inv9;
			});
	}
	#pragma endscop
